const express = require('express');
const db = require('../db');
const jwt = require('jsonwebtoken');
const router = express.Router();

/* -------------------- AUTH MIDDLEWARE -------------------- */
function authMiddleware(req, res, next) {
  const auth = req.headers.authorization;
  if (!auth) return res.status(401).json({ message: 'No token' });

  const token = auth.split(' ')[1];
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET || 'secret');
    next();
  } catch (e) {
    return res.status(401).json({ message: 'Invalid token' });
  }
}

/* -------------------- NEW: VIEW ALL REGISTERED NGOs -------------------- */
router.get('/list-ngos', async (req, res) => {
  try {
    const [rows] = await db.query('SELECT id, name, description FROM ngos ORDER BY id DESC');
    res.json({ ngos: rows });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

/* -------------------- NEW: VIEW ALL REGISTERED EVENTS -------------------- */
router.get('/list-events', async (req, res) => {
  try {
    const [rows] = await db.query('SELECT * FROM events ORDER BY id DESC');
    res.json({ events: rows });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

/* -------------------- NGO-CREATED EVENTS ONLY -------------------- */
router.get('/ngo-events', authMiddleware, async (req, res) => {
  try {
    const [rows] = await db.query(
      'SELECT * FROM events WHERE created_by = ? ORDER BY id DESC',
      [req.user.id]
    );
    res.json({ events: rows });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

/* -------------------- CREATE EVENT -------------------- */
router.post('/create-event', authMiddleware, async (req, res) => {
  if (!['NGO', 'Admin'].includes(req.user.role))
    return res.status(403).json({ message: 'Forbidden' });

  const { title, description, image_url } = req.body;

  try {
    const [result] = await db.query(
      'INSERT INTO events (title, description, image_url, created_by) VALUES (?,?,?,?)',
      [title, description, image_url || null, req.user.id]
    );

    const [rows] = await db.query('SELECT * FROM events WHERE id = ?', [
      result.insertId,
    ]);

    res.json({ message: 'Event created', event: rows[0] });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

/* -------------------- NGO PANEL STATS -------------------- */
router.get('/panel', authMiddleware, async (req, res) => {
  try {
    const [[{ totalEvents }]] = await db.query(
      'SELECT COUNT(*) AS totalEvents FROM events WHERE created_by = ?',
      [req.user.id]
    );

    const [[{ totalVolunteers }]] = await db.query(
      `SELECT COUNT(v.id) AS totalVolunteers
       FROM volunteers v
       LEFT JOIN events e ON v.event_id = e.id
       WHERE e.created_by = ?`,
      [req.user.id]
    );

    const [[{ totalDonations }]] = await db.query(
      'SELECT IFNULL(SUM(amount),0) AS totalDonations FROM donations WHERE ngo_id = ?',
      [req.user.id]
    );

    res.json({
      name: req.user.name,
      totalEvents,
      totalVolunteers,
      totalDonations,
    });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

/* -------------------- NGO VOLUNTEERS -------------------- */
router.get('/volunteers', authMiddleware, async (req, res) => {
  try {
    const [rows] = await db.query(
      `SELECT v.id, v.created_at, u.name as user_name, u.email, 
              e.id as event_id, e.title as event_title
       FROM volunteers v
       LEFT JOIN users u ON v.user_id = u.id
       LEFT JOIN events e ON v.event_id = e.id
       WHERE e.created_by = ?
       ORDER BY v.created_at DESC`,
      [req.user.id]
    );

    res.json({ volunteers: rows });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

/* -------------------- NGO DONATIONS -------------------- */
router.get('/donations', authMiddleware, async (req, res) => {
  try {
    const [rows] = await db.query(
      `SELECT d.id, d.amount, d.created_at,
              u.name as donor_name, u.email as donor_email
       FROM donations d
       LEFT JOIN users u ON d.user_id = u.id
       WHERE d.ngo_id = ?
       ORDER BY d.created_at DESC`,
      [req.user.id]
    );

    res.json({ donations: rows });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

/* -------------------- ACHIEVEMENTS -------------------- */
router.get('/achievements', authMiddleware, async (req, res) => {
  if (!['NGO', 'Admin'].includes(req.user.role))
    return res.status(403).json({ message: 'Forbidden' });

  try {
    const [[{ successfulEvents }]] = await db.query(
      `SELECT COUNT(*) AS successfulEvents
       FROM (
         SELECT e.id
         FROM events e
         LEFT JOIN volunteers v ON v.event_id = e.id
         WHERE e.created_by = ?
         GROUP BY e.id
         HAVING COUNT(v.id) > 0
       ) x`,
      [req.user.id]
    );

    const [topEvents] = await db.query(
      `SELECT e.id, e.title, e.image_url, COUNT(v.id) AS volunteers_count
       FROM events e
       LEFT JOIN volunteers v ON v.event_id = e.id
       WHERE e.created_by = ?
       GROUP BY e.id
       ORDER BY volunteers_count DESC
       LIMIT 6`,
      [req.user.id]
    );

    res.json({ successfulEvents, topEvents });
  } catch (err) {
    console.error(err);
    res.status(500).json({ message: 'Server error' });
  }
});

module.exports = router;
